		public void onSlotChanged() {
			super.onSlotChanged();

			if(!trimmingTable.getStackInSlot(4).isEmpty()) {
				int index = this.getSlotIndex();

				if(index == 1 || index == 2 || index == 3) {
					int removed = Math.max(0, this.prevCount - this.getStack().getCount());

